<?php require '../config/auth.php';require '../config/database.php';wajibPelanggan();$id=(int)$_GET['id'];$q=$pdo->prepare('SELECT t.*,u.nama FROM transactions t JOIN users u ON u.id=t.user_id WHERE t.id=? AND t.user_id=?');$q->execute([$id,$_SESSION['user_id']]);$t=$q->fetch(PDO::FETCH_ASSOC);$q=$pdo->prepare('SELECT ti.*,p.nama FROM transaction_items ti JOIN products p ON p.id=ti.product_id WHERE ti.transaction_id=?');$q->execute([$id]);$items=$q->fetchAll(PDO::FETCH_ASSOC);?><!doctype html><html lang="id"><head><meta charset="utf-8"><title>Invoice #<?=$id?></title><link rel="stylesheet" href="../assets/css/style.css"><script src="https://cdn.jsdelivr.net/npm/sweetalert2@11"></script><script src="../assets/js/sweetalert.js"></script><style>@media print{button,a{display:none!important}}.invoice{max-width:800px;margin:50px auto;background:#fff;padding:40px}</style></head><body><div class="invoice"><h1>StyleKita</h1><p>Invoice #<?=$id?> — <?=$t['created_at']?></p><p>Pelanggan: <?=$t['nama']?></p><?php foreach($items as $x):?><div class="tr"><span><?=$x['nama']?> × <?=$x['qty']?></span><b>Rp <?=number_format($x['harga']*$x['qty'],0,',','.')?></b></div><?php endforeach;?><h2>Total Rp <?=number_format($t['total'],0,',','.')?></h2><p>Pembayaran: <?=$t['pembayaran']?> | Pengiriman: <?=$t['pengiriman']?></p><button class="btn" onclick="print()">Cetak Invoice</button><a class="btn" href="profil.php">Kembali</a></div></body></html>
